const validRevision=ref('')
import FlowNode from './FlowNode.vue'
const localDialog=ref(null),service=ref(slots.default?'LM Studio':'Ollama'),address=ref(''),modelId=ref(''),available=ref([]),feedback=ref('')
async function readConnection(){available.value=[];feedback.value='';const settings=await api('load',{action:'local-settings'});const saved=settings[service.value];address.value=saved?.url||(service.value==='Ollama'?'http://127.0.0.1:11434/v1':'http://127.0.0.1:1234/v1');modelId.value=saved?.model||'';if(modelId.value)available.value=[modelId.value]}
async function listModels(){try{available.value=await api('load',{action:'local-list',url:address.value});modelId.value=available.value.includes(modelId.value)?modelId.value:(available.value[0]||'');feedback.value=modelId.value?'连接成功':'模型列表为空，请先在服务中加载模型'}catch(e){available.value=[];modelId.value='';feedback.value='连接失败 · '+e.message}}
async function saveConnection(){try{await api('load',{action:'local-save',service:service.value,url:address.value,model:modelId.value});feedback.value='已保存，下次运行时生效'}catch(e){feedback.value='保存失败 · '+e.message}}
const clone=v=>JSON.parse(JSON.stringify(v))
const labels=ref({}),defaults=ref({}),catalog=ref(null),base=ref(null),nodes=ref([]),edges=ref([]),snapshot=ref(null),pinned=ref(null)
const modelSamples=ref({}),modelChoice=ref('p08.openai.text');const approvalDetails=ref([]);const search=ref(''),error=ref(''),notice=ref(''),connection=ref('正在连接'),busy=ref(false),saved=ref(false),name=ref('flow-'+crypto.randomUUID().slice(0,8)),tab=ref('overview'),events=ref([]),picking=ref(null),fileInput=ref(null)
const history=ref([]),future=ref([]),left=ref(true),right=ref(true),bottom=ref(true),compact=ref(false),lw=ref(220),rw=ref(300),bh=ref(180),restored=ref(false)
const {fitView,zoomIn,zoomOut,screenToFlowCoordinate,viewport,updateNodeInternals,getSelectedNodes,getNodes,removeSelectedNodes,addSelectedNodes}=useVueFlow()
let narrow=false,normalPanels=null;function responsive(){if(innerWidth<1150&&!narrow){normalPanels={left:left.value,right:right.value};left.value=false;right.value=false;narrow=true}else if(innerWidth>=1150&&narrow){left.value=normalPanels.left;right.value=normalPanels.right;narrow=false}};let pendingFit=true; let sampleDoc=null,approvalDoc=null,pollHandle=null,stopped=false,requestTail=Promise.resolve(),eventsAfter=0
const statusNames={'queued':'等待依赖','running':'运行中','succeeded':'完成','failed':'失败','cancelled':'已取消','waiting-approval':'等待审批','cancel-requested':'取消中','skipped':'已跳过','unknown':'结果未知'}
const icons={'queued':'○','running':'◌','succeeded':'✓','failed':'×','cancelled':'■','waiting-approval':'◇','unknown':'?','skipped':'↷','cancel-requested':'◼'}
function labelState(s){return (icons[s]||'—')+' '+(statusNames[s]||'待运行')}
function def(t,v='0.1.0'){return catalog.value?.nodeDefinitions.find(d=>d.typeId===t&&d.version===v)}
function ports(n){const known=def(n.typeId,n.typeVersion);if(known)return known.ports.filter(p=>p.channel==='data');const found=new Map();for(const e of base.value?.graph.edges||[]){if(e.from.node===n.id)found.set('o'+e.from.port,{id:e.from.port,direction:'output',type:{name:'未知端口'}});if(e.to.node===n.id)found.set('i'+e.to.port,{id:e.to.port,direction:'input',type:{name:'未知端口'}})}return [...found.values()]}
function definition(){if(!base.value)return null;const w=clone(base.value);w.graph.nodes=w.graph.nodes.filter(n=>nodes.value.some(f=>f.id===n.id));w.graph.edges=edges.value.map(e=>({...clone(e.data?.original||{}),id:e.id,kind:e.data?.original?.kind||'data',from:{node:e.source,port:e.sourceHandle},to:{node:e.target,port:e.targetHandle},order:e.data?.original?.order||0}));return w}
function document(){return {workflow:definition(),layout:{version:'aos-layout/0.1',positions:Object.fromEntries(nodes.value.map(n=>[n.id,{x:n.position.x,y:n.position.y}]))}}}
function nodeChanges(changes){for(const c of changes){const n=nodes.value.find(n=>n.id===c.id);if(n&&c.type==="select")n.selected=c.selected;if(n&&c.type==="position"&&c.position)n.position={...c.position}}}
function edgeChanges(changes){for(const c of changes){const e=edges.value.find(e=>e.id===c.id);if(e&&c.type==="select")e.selected=c.selected}}
function capture(){if(base.value){history.value.push(document());if(history.value.length>80)history.value.shift();future.value=[]}}
function touch(){base.value.version={revision:'draft-'+crypto.randomUUID().slice(0,12)};saved.value=false;error.value='';notice.value='草稿已修改'}
function applyDoc(d){removeSelectedNodes(getSelectedNodes.value);pendingFit=true;base.value=clone(d.workflow);nodes.value=d.workflow.graph.nodes.map(n=>({id:n.id,type:'aos',position:clone(d.layout?.positions[n.id]||{x:0,y:0}),data:{}}));edges.value=d.workflow.graph.edges.map(e=>({id:e.id,source:e.from.node,sourceHandle:e.from.port,target:e.to.node,targetHandle:e.to.port,data:{original:clone(e)}}));saved.value=false;nextTick(()=>{updateNodeInternals();setTimeout(()=>fitView({padding:.06,maxZoom:1}),80)})}
