const selected=computed(()=>base.value?.graph.nodes.find(n=>getSelectedNodes.value.some(f=>f.id===n.id)))
const selectedCount=computed(()=>getSelectedNodes.value.length)
const fields=computed(()=>{const d=selected.value&&def(selected.value.typeId,selected.value.typeVersion);return Object.entries(d?.configSchema?.properties||{})})
const area=ref('工作流'), documents=ref([]), availableLocal=ref({}), onlyReady=ref(false), welcome=ref(true)
const groups=['输入与输出','数据处理','模型','MCP 工具']
function groupOf(t){
  if(['synth.source','synth.output'].includes(t))return groups[0]
  if(t==='p07.model'||def(t)?.executionKind==='model')return groups[2]
  if(def(t)?.executionKind==='tool')return groups[3]
  return groups[1]
}
const descriptions={'synth.source':'输入固定文本','synth.output':'显示上游输出','synth.step':'给文本追加后缀','p07.model':'离线生成合成回答','p08.join':'合并多个文本输入'}
function localName(t){return {'p08.lmstudio.text':'LM Studio','p08.ollama.text':'Ollama'}[t]}
function missing(t){return localName(t)&&!availableLocal.value[localName(t)]}
function describe(t){return (def(t)?.executionKind==='tool'?'调用本机合成 MCP 工具':null)||descriptions[t]||(missing(t)?'请先配置本地模型连接':localName(t)?'使用已配置的本地模型':groupOf(t)==='模型'?'通过 SDK 请求离线测试服务':(def(t)?.ports||[]).filter(p=>p.channel==='data'&&p.type.name!=='Error').map(p=>p.type.schemaRef||p.type.name).join(' → '))}
const palette=computed(()=>(catalog.value?.nodeDefinitions||[]).filter(d=>labels.value[d.typeId]).map(d=>[d.typeId,labels.value[d.typeId]]).filter(([t,l])=>(!onlyReady.value||!missing(t))&&[t,l,describe(t),groupOf(t)].join(' ').toLowerCase().includes(search.value.trim().toLowerCase())))
const treeItems=computed(()=>groups.map(group=>({key:group,label:group,children:palette.value.filter(([tid])=>groupOf(tid)===group).map(([tid,label])=>({key:tid,label,disabled:!!missing(tid)}))})).filter(g=>g.children.length))
function renderCatalog({option}){
 if(option.children)return option.label
 const tid=option.key
 return h('button',{class:'catalog-choice','data-type':tid,disabled:option.disabled,onClick:()=>{add(tid);welcome.value=false}},[h('strong',option.label),h('small',describe(tid))])
}
async function refresh(){documents.value=await api('load',{action:'list-documents'});availableLocal.value=await api('load',{action:'local-settings'})}
async function navigate(next){shell.value?.show({'工作流':'files','节点库':'nodes','连接':'connections'}[next]);await action(refresh)}
function startDraft(empty){
 const doc=clone(sampleDoc);doc.workflow.workflowId='flow-'+crypto.randomUUID();name.value='flow-'+crypto.randomUUID().slice(0,8)
 if(empty){doc.workflow.graph={nodes:[],edges:[]};doc.workflow.environmentRequirements=[];doc.layout.positions={};doc.workflow.title='未命名工作流'}
 capture();applyDoc(doc);touch();welcome.value=false;area.value=empty?'节点库':'工作流';left.value=true;shell.value?.show(empty?'nodes':'files')
}
function placement(){
 const box=window.document.querySelector('.vue-flow').getBoundingClientRect()
 const cells=[.08,.48,.71].flatMap(y=>[.05,.4,.66].map(x=>screenToFlowCoordinate({x:box.left+box.width*x,y:box.top+box.height*y})))
 return cells.find(p=>nodes.value.every(n=>Math.abs(n.position.x-p.x)>242||Math.abs(n.position.y-p.y)>190))||{x:Math.max(...nodes.value.map(n=>n.position.x))+250,y:nodes.value[0]?.position.y||0}
}
const approvals=computed(()=>Object.values(snapshot.value?.approvals||{}).filter(a=>a.status==='pending').map(a=>({...a,...approvalDetails.value.find(d=>d.id===a.id&&d.fingerprint===a.fingerprint)})))
const terminal=computed(()=>['succeeded','failed','cancelled','unknown'].includes(snapshot.value?.state))
