const problems=computed(()=>Object.values(snapshot.value?.nodes||{}).filter(n=>n.error).map(n=>({id:n.nodeId||n.key,message:n.error.code})))
const taskProvider=ref('Ollama'),resultName=ref('tasks'),openedTasks=ref(null)
async function loadTask(){await action(async()=>{const doc=await api('load',{action:'task-template',provider:taskProvider.value});capture();applyDoc(doc);welcome.value=false;name.value='tasks-'+crypto.randomUUID().slice(0,8);touch();notice.value='在文本输入节点填写会议记录，运行后检查任务清单'})}
async function taskFile(save){await action(async()=>{const body={action:save?'task-save':'task-open',name:resultName.value};if(save)body.runId=snapshot.value.runId;const data=await api('load',body);if(!save)openedTasks.value=data;notice.value=save?'已保存至 workspace/results/'+data.saved:'已打开结果文件'})}
const result=computed(()=>snapshot.value?.scopes?.main?.result)
function nodeData(id){const i=nodes.value.findIndex(f=>f.id===id);const n=base.value.graph.nodes.find(n=>n.id===id);const r=pinned.value?.workflowId===base.value.workflowId && pinned.value?.version.revision===base.value.version.revision ? snapshot.value?.nodes['main/'+id] : null;const old=pinned.value?.graph.nodes.find(n=>n.id===id);return {spec:n,ports:ports(n),label:labels.value[n.typeId]||'未知节点 · '+n.typeId,ordinal:String(i+1).padStart(2,'0'),symbol:n.typeId.startsWith('tool.')?'⌁':n.typeId==='p07.model'?'◇':n.typeId.startsWith('synth.output')?'↗':'▤',preview:preview(n),state:r?.state||'',status:labelState(r?.state),badge:n.typeId==='p07.model'?'MOCK':n.typeId.startsWith('tool.')?'MCP':'',edited:old&&JSON.stringify(old)!==JSON.stringify(n)}}
provide('aos-graph',{nodeData})
function preview(n){return n.config.value||n.config.suffix||(n.typeId==='p07.model'?`${n.config.maxOutputTokens} 字符 · ${n.config.delayMs} ms`:n.config.operation||(!def(n.typeId,n.typeVersion)?'缺少兼容描述，禁止执行':''))}
// Only transport reads are polled. Every displayed business state comes from C1.
function api(op,body={}){const id='ui-'+crypto.randomUUID();const task=requestTail.catch(()=>{}).then(async()=>{if(!window.__TAURI__?.core)throw Error('真实 Tauri 桥不可用');const r=await window.__TAURI__.core.invoke('host_request',{request:{v:'aos-local/0.1',kind:'request',id,op,body}});if(r.id!==id)throw Error('IPC_RESPONSE_ID_MISMATCH');if(!r.ok)throw Error(r.error.code);return r.result});requestTail=task;return task}
async function action(fn){error.value='';busy.value=true;try{return await fn()}catch(e){error.value=({'REQUIRED_INPUT_MISSING':'必需输入尚未连线','EXACTLY_ONE_OUTPUT_REQUIRED':'请添加一个文本输出节点','DISCONNECTED_NODE':'请将所有节点连接到输出','DOCUMENT_NAME_DENIED':'保存名称请使用 1–48 个字母、数字、短横线或下划线','LOCAL_CONNECTION_NOT_CONFIGURED':'请先在连接面板配置本地模型'}[e.message]||String(e.message||e));tab.value='problems'}finally{busy.value=false}}
async function validate(){return action(async()=>{const r=await api('load',{action:'validate',workflow:definition()});validRevision.value=base.value.version.revision;notice.value='C1 契约校验通过 · '+r.workflowDigest.slice(0,12);return r})}
// View-only cache. C1 still supplies the run identity, definition and all business state.
const runLayoutKey='aos-workbench.p011.last-run-layout'
function rememberRunLayout(runId,workflow,layout){
 try{localStorage.setItem(runLayoutKey,JSON.stringify({runId,workflowId:workflow.workflowId,revision:workflow.version.revision,layout}))}
 catch{notice.value='运行已启动，本机未保存画布位置'}
}
function layoutForRun(runId,workflow){
 try{
  const cached=JSON.parse(localStorage.getItem(runLayoutKey)||'null')
  if(cached?.runId===runId && cached.workflowId===workflow.workflowId && cached.revision===workflow.version.revision &&
     workflow.graph.nodes.every(n=>{const p=cached.layout?.positions?.[n.id];return Number.isFinite(p?.x)&&Number.isFinite(p?.y)}))return cached.layout
 }catch{}
 return {version:'aos-layout/0.1',positions:Object.fromEntries(workflow.graph.nodes.map((n,i)=>[n.id,{x:(i%4)*250,y:Math.floor(i/4)*170}]))}
}
async function run(){if(!canRun.value)return;return action(async()=>{const {workflow:w,layout}=document();const r=await api('load',{action:'validate',workflow:w});const s=await api('create',{token:r.token});rememberRunLayout(s.runId,w,layout);validRevision.value=w.version.revision;pinned.value=clone(w);snapshot.value=s;events.value=[];eventsAfter=0;notice.value='已固定运行修订 '+s.workflowRevision;tab.value='overview'})}
async function save(){return action(async()=>{await api('load',{action:'save',name:name.value,document:document()});saved.value=true;await refresh();notice.value='已保存 · '+name.value})}
async function open(){return action(async()=>{const d=await api('load',{action:'open',name:name.value});capture();applyDoc(d);saved.value=true;welcome.value=false;notice.value='已重新加载 · '+name.value})}
async function cancel(){return action(async()=>{snapshot.value=await api('cancel');notice.value='已请求取消，等待 C1 确认'})}
async function decide(a,decision){return action(async()=>{snapshot.value=await api('approve',{approvalId:a.id,fingerprint:a.fingerprint,decision});notice.value=decision?'批准已提交，C1 核验后派发':'已拒绝'})}
async function poll(){if(stopped)return;try{if(snapshot.value){const s=await api('status');if(s.runId===snapshot.value.runId){snapshot.value=s;if(Object.values(s.approvals).some(a=>a.status==='pending'))approvalDetails.value=await api('approvals');else approvalDetails.value=[];const batch=await api('events',{after:eventsAfter});if(batch.runId===s.runId){for(const e of batch.events){if(e.seq>eventsAfter){events.value.push(e);eventsAfter=e.seq}}}if(events.value.length>500)events.value=events.value.slice(-500)}}}catch(e){connection.value='执行器断连 · 结果待核实';error.value='IPC：'+e.message;tab.value='problems'}finally{if(!stopped)pollHandle=setTimeout(poll,300)}}
function add(tid,pos){capture();const id='n'+crypto.randomUUID().slice(0,8);const n={id,typeId:tid,typeVersion:'0.1.0',enabled:true,config:clone(defaults.value[tid]||{}),policy:clone(base.value.executionPolicy)};if(tid.startsWith('tool.mcp.')){const name=tid.slice(9);n.adapter={id:'fixture.p04.'+name,version:'0.1.0',capabilityId:'cap.fixture.p04.'+name};n.serviceSlot='tool.'+name}if(def(tid)?.executionKind==='model'){n.adapter={id:'fixture.'+tid,version:'0.1.0',capabilityId:'cap.fixture.'+tid};n.serviceSlot=tid}base.value.graph.nodes.push(n);nodes.value.forEach(n=>n.selected=false);nodes.value.push({id,type:'aos',position:pos||placement(),data:{},selected:true});updateRequirements();touch();nextTick(()=>{const v=window.document.querySelector('.vue-flow')?.getBoundingClientRect();const card=window.document.querySelector('[data-node-id="'+id+'"]')?.getBoundingClientRect();if(v&&card&&(card.right>v.right||card.bottom>v.bottom||card.left<v.left||card.top<v.top))fitView({padding:.12,maxZoom:1})})}
function updateRequirements(){base.value.environmentRequirements=['echo_text','simulated_effect'].filter(name=>base.value.graph.nodes.some(n=>nodes.value.some(f=>f.id===n.id)&&n.typeId==='tool.mcp.'+name)).map(name=>({slot:'tool.'+name,kind:'service',required:true,adapter:{id:'fixture.p04.'+name,version:'0.1.0',capabilityId:'cap.fixture.p04.'+name},permissions:['synthetic:tool:'+name]}));for(const n of base.value.graph.nodes.filter(n=>def(n.typeId)?.executionKind==='model')){if(!base.value.environmentRequirements.some(r=>r.slot===n.typeId))base.value.environmentRequirements.push({slot:n.typeId,kind:'service',required:true,adapter:clone(n.adapter),permissions:['synthetic:model-http']})}}
function remove(){capture();const selected=new Set(getSelectedNodes.value.map(n=>n.id));nodes.value=nodes.value.filter(n=>!selected.has(n.id));base.value.graph.nodes=base.value.graph.nodes.filter(n=>!selected.has(n.id));edges.value=edges.value.filter(e=>!e.selected&&!selected.has(e.source)&&!selected.has(e.target));updateRequirements();touch()}
function duplicate(){capture();const chosen=nodes.value.filter(n=>getSelectedNodes.value.some(f=>f.id===n.id));const ids=new Map(chosen.map(n=>[n.id,'n'+crypto.randomUUID().slice(0,8)]));for(const n of chosen){const spec=clone(base.value.graph.nodes.find(s=>s.id===n.id));spec.id=ids.get(n.id);base.value.graph.nodes.push(spec);nodes.value.push({...clone(n),id:spec.id,position:{x:n.position.x+32,y:n.position.y+32},selected:true});n.selected=false}for(const e of [...edges.value])if(ids.has(e.source)&&ids.has(e.target))edges.value.push({...clone(e),id:'e'+crypto.randomUUID(),source:ids.get(e.source),target:ids.get(e.target)});updateRequirements();touch()}
function connectionError(c){if(c.source===c.target)return '不能连接到自身';const a=base.value.graph.nodes.find(n=>n.id===c.source),b=base.value.graph.nodes.find(n=>n.id===c.target);if(!a||!b||!def(a.typeId,a.typeVersion)||!def(b.typeId,b.typeVersion))return '未知节点不能建立新的执行连接';const pa=a&&ports(a).find(p=>p.id===c.sourceHandle),pb=b&&ports(b).find(p=>p.id===c.targetHandle);if(!pa||!pb||pa.direction!=='output'||pb.direction!=='input')return '端口方向无效';if(JSON.stringify(pa.type)!==JSON.stringify(pb.type))return '类型不兼容：'+(pa.type.schemaRef||pa.type.name)+' → '+(pb.type.schemaRef||pb.type.name);if(pb.cardinality!=='many'&&edges.value.some(e=>e.target===c.target&&e.targetHandle===c.targetHandle))return '该输入已有连接，请先删除原连线';const reach=new Set([c.target]);let size;do{size=reach.size;for(const e of edges.value)if(reach.has(e.source))reach.add(e.target)}while(size!==reach.size);return reach.has(c.source)?'连接会形成无界循环':''}
function validConnection(c){if(edges.value.some(e=>e.source===c.source&&e.sourceHandle===c.sourceHandle&&e.target===c.target&&e.targetHandle===c.targetHandle))return true;const reason=connectionError(c);if(reason){error.value=reason;return false}return true}
function connect(c){const reason=connectionError(c);if(reason){error.value=reason;return}capture();edges.value.push({id:'e'+crypto.randomUUID(),...c,data:{original:{order:Math.max(-1,...edges.value.filter(e=>e.target===c.target&&e.targetHandle===c.targetHandle).map(e=>e.data?.original?.order||0))+1}}});touch();picking.value=null}
function setField(key,s,e){capture();let value=s.const!==undefined?s.const:s.type==='boolean'?e.target.checked:['integer','number'].includes(s.type)?(e.target.value===''?null:Number(e.target.value)):e.target.value;selected.value.config[key]=value;touch()}
function drop(e){e.preventDefault();const tid=e.dataTransfer.getData('application/aos-node');if(labels.value[tid])add(tid,screenToFlowCoordinate({x:e.clientX,y:e.clientY}))}
function chooseModel(){capture();applyDoc(clone(modelSamples.value[modelChoice.value]));touch()}
function setBudget(key,e){capture();const v=Number(e.target.value);if(key==='concurrencyLimit')base.value.executionPolicy[key]=v;else base.value.executionPolicy.budget[key]=v;touch()}
function reset(effect=false){capture();applyDoc(clone(effect?approvalDoc:sampleDoc));history.value=[];future.value=[];notice.value=effect?'已载入审批合成场景':'已载入合成场景'}
function resize(which,e){const start=e.clientX,sy=e.clientY,old=which==='left'?lw.value:which==='right'?rw.value:bh.value;const move=ev=>{if(which==='left')lw.value=Math.max(184,Math.min(360,old+ev.clientX-start));else if(which==='right')rw.value=Math.max(272,Math.min(480,old-ev.clientX+start));else bh.value=Math.max(96,Math.min(innerHeight*.5,old-ev.clientY+sy))};const end=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);prefs()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end)}
function resizeKey(which,e){if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const d=(e.shiftKey?32:8)*(['ArrowRight','ArrowDown'].includes(e.key)?1:-1);if(which==='left')lw.value=Math.max(184,Math.min(360,lw.value+d));else if(which==='right')rw.value=Math.max(272,Math.min(480,rw.value-d));else bh.value=Math.max(96,Math.min(innerHeight*.5,bh.value-d));prefs()}
function prefs(){localStorage.setItem('aos-p008-view',JSON.stringify({left:left.value,right:right.value,bottom:bottom.value,compact:compact.value,lw:lw.value,rw:rw.value,bh:bh.value}))}
watch([left,right,bottom,compact],prefs)
function shortcut(e){const input=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if(e.ctrlKey&&e.key.toLowerCase()==='s'){e.preventDefault();if(input)e.target.blur();save();return}if(input||e.target.isContentEditable)return;if(e.key==='+'||e.key==='='){zoomIn();return}if(e.key==='-'){zoomOut();return}if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();if(canRun.value)run()}else if(e.shiftKey&&e.key==='F5'){e.preventDefault();cancel()}else if(e.ctrlKey&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}else if(e.ctrlKey&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate()}else if(e.ctrlKey&&e.key.toLowerCase()==='a'){e.preventDefault();addSelectedNodes(getNodes.value)}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove()}else if(e.key==='Home'){e.preventDefault();fitView({padding:.06,maxZoom:1})}else if(shell.value&&e.ctrlKey&&e.key==='b'){e.preventDefault();e.altKey?shell.value.cfg.secondarySideBar=!shell.value.cfg.secondarySideBar:shell.value.cfg.primarySideBar=!shell.value.cfg.primarySideBar}else if(shell.value&&e.ctrlKey&&e.key==='j'){e.preventDefault();shell.value.cfg.bottomPanel=!shell.value.cfg.bottomPanel}else if(e.key==='Escape')picking.value=null}
function download(){const blob=new Blob([JSON.stringify(document(),null,2)],{type:'application/json'});const a=window.document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name.value+'.aos.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importFile(e){return action(async()=>{const file=e.target.files[0];if(!file)return;if(file.size>240000)throw Error('文件超过 240 KB');const d=JSON.parse(await file.text());if(!d.workflow?.graph||!Array.isArray(d.workflow.graph.nodes)||!Array.isArray(d.workflow.graph.edges))throw Error('文档结构无效');capture();applyDoc(d);notice.value='已导入草稿，运行前必须通过 C1 校验';e.target.value=''})}
onMounted(async()=>{window.addEventListener('keydown',shortcut);window.addEventListener('resize',responsive);responsive();try{const p=JSON.parse(localStorage.getItem('aos-p008-view')||'null');if(p){for(const [k,r] of Object.entries({left,right,bottom,compact,lw,rw,bh}))if(p[k]!==undefined)r.value=p[k]}}catch{}await action(async()=>{connection.value='正在启动执行器';await api('host.start');const h=await api('health');catalog.value=h.catalog;labels.value=h.labels;defaults.value=h.defaults;modelSamples.value=h.modelSamples;sampleDoc=h.sample;approvalDoc=h.approvalSample;applyDoc(slots.default?h.modelSamples['p08.lmstudio.text']:sampleDoc);if(slots.default){welcome.value=false;base.value.title='本地文本工作流'}await refresh();connection.value='C1 已连接';notice.value='默认使用离线合成工作流';try{const s=await api('recover');snapshot.value=s;pinned.value=await api('load',{action:'run-definition'});applyDoc({workflow:pinned.value,layout:layoutForRun(s.runId,pinned.value)});restored.value=true;welcome.value=false;notice.value='已恢复原运行 · '+s.runId}catch(e){if(!['RUN_NOT_FOUND','NO_OPEN_RUN'].includes(e.message)){connection.value='恢复待核实';error.value='恢复失败：'+e.message}}});poll()})
onUnmounted(()=>{stopped=true;clearTimeout(pollHandle);window.removeEventListener('keydown',shortcut);window.removeEventListener('resize',responsive)})
function loadExample(d){
 capture();applyDoc(d);welcome.value=false;name.value=d.workflow.workflowId+'-'+crypto.randomUUID().slice(0,8)
}
const controller=reactive({catalog,labels,base,nodes,edges,selected,fields,groups,groupOf,palette,search,selectedCount,
 connection,busy,saved,error,name,documents,snapshot,pinned,approvals,events,result,problems,canRun,terminal,viewport,
 service,address,modelId,available,feedback,availableLocal,readConnection,listModels,saveConnection,refresh,add,remove,duplicate,undo,redo,
 startDraft,loadExample,open,save,validate,run,cancel,decide,touch,setField,validConnection,connect,fitView,zoomIn,zoomOut,
 drop,capture,ports,picking,nodeData,labelState,download,importFile,api})
</script>

<template>
<slot v-if="slots.default" :workbench="controller"/>
<n-config-provider v-else :theme="darkTheme" :theme-overrides="theme" class="studio-app"><main class="studio-frame">
 <nav class="toolbar" aria-label="工作流工具栏"><input class="workflow-title" aria-label="工作流标题" v-if="base" v-model="base.title" @change="touch"><span class="dirty">{{saved?'已保存':'草稿'}}</span><div class="tools"><button :disabled="!base" @click="startDraft(true)">新建</button><button @click="navigate('工作流',false)">打开</button><button @click="save" :disabled="busy||!base" title="Ctrl+S">保存</button><button @click="validate" :disabled="busy||!base">校验</button><div class="tool-divider"/><button class="primary" data-testid="run" @click="run" :disabled="!canRun">▶ 运行</button><button data-testid="cancel" @click="cancel" :disabled="!snapshot||terminal||busy">■ 取消</button></div><div class="spacer"/><span class="run-state" :class="snapshot?.state" data-testid="run-state">{{snapshot&&connection!=='C1 已连接'?'? 连接中断 · 待核实':labelState(snapshot?.state)}}</span></nav>
 <div v-if="error" class="error-banner" role="alert"><strong>× {{connection.includes('断连')?'连接中断，以下为最后确认状态。 ':''}}{{error}}</strong><button @click="error=''" aria-label="关闭错误">×</button></div>
 <div v-if="approvals.length" class="approval-banner"><strong>◇ 等待人工审批</strong><span>操作正在等待检查。请核对下方固定动作。</span><button @click="shell.cfg.bottomPanel=true;tab='overview'">查看动作</button></div>
 <StudioShell ref="shell">
 <template #editor>  <section class="editor" aria-label="工作流画布">
   <div class="canvas-head"><span>工作流 <small>{{nodes.length}} 节点 · {{edges.length}} 连线</small></span><div><button @click="undo" :disabled="!history.length" title="撤销 Ctrl+Z">↶</button><button @click="redo" :disabled="!future.length" title="重做 Ctrl+Shift+Z">↷</button><button @click="duplicate" :disabled="!selectedCount" title="复制 Ctrl+D">复制</button><button @click="remove" :disabled="!selectedCount&&!edges.some(e=>e.selected)" title="Delete">删除</button></div></div>
   <div v-if="welcome&&catalog" class="welcome"><h2>工作流工作台</h2><p>打开离线示例，点击运行即可查看结果。</p><button class="primary" @click="startDraft(false)">使用离线示例</button><button @click="startDraft(true)">新建空白工作流</button><button @click="navigate('工作流',false)">浏览已保存工作流</button></div><VueFlow v-show="!welcome" @nodes-initialized="()=>{if(pendingFit){fitView({padding:.06,maxZoom:1});pendingFit=false}}" v-model:nodes="nodes" v-model:edges="edges"  :min-zoom=".25" :max-zoom="2" :is-valid-connection="validConnection" :delete-key-code="null" :selection-key-code="'Shift'" :multi-selection-key-code="'Shift'" :pan-on-drag="[1,2]" :pan-activation-key-code="'Space'" :zoom-activation-key-code="'Control'" :zoom-on-scroll="false" :zoom-on-pinch="true" @connect="connect" @node-drag-start="capture" @node-drag-stop="saved=false" :snap-to-grid="true" :snap-grid="[8,8]">
    <template #node-aos="props"><FlowNode v-bind="props"/></template><Background pattern-color="#2c3540" :gap="20" :size="1"/>
   </VueFlow>
   <div class="canvas-footer"><span>{{selectedCount?selectedCount+' 个节点已选择':'Space 平移 · Ctrl+滚轮缩放'}}</span><div><button @click="zoomOut" aria-label="缩小">−</button><span>{{Math.round(viewport.zoom*100)}}%</span><button @click="zoomIn" aria-label="放大">+</button><button @click="fitView({padding:.06,maxZoom:1})" title="Home">适应画布</button></div></div>
  </section>
</template>
 <template #files-view><section class="side-content"><label>保存名称<input aria-label="文档名称" v-model="name" maxlength="48"></label><small>使用字母、数字、短横线或下划线</small><h3>已保存的工作流</h3><p v-if="!documents.length">尚无已保存的工作流</p><button v-for="doc in documents" @click="name=doc;open()">{{doc}}</button><h3>本地 AI 文本任务提取</h3><label>模型连接<select aria-label="提取模型" v-model="taskProvider"><option>Ollama</option><option>LM Studio</option></select></label><button @click="loadTask">打开任务提取工作流</button><label>结果文件名<input aria-label="结果文件名" v-model="resultName" maxlength="48"></label><small>保存至 workspace/results/{{resultName}}.json</small><button @click="taskFile(true)" :disabled="snapshot?.state!=='succeeded'||!Object.values(snapshot?.approvals||{}).some(a=>a.key==='main/output'&&a.status==='consumed')">保存已检查结果</button><button @click="taskFile(false)">重新打开结果</button><pre v-if="openedTasks" data-testid="opened-tasks">{{JSON.stringify(openedTasks,null,2)}}</pre><h3>示例</h3><button @click="startDraft(false)">打开离线示例</button><button @click="reset(true);welcome=false">打开审批示例</button><h3>文件</h3><button @click="fileInput.click()">导入 JSON</button><button @click="download" :disabled="!base">导出 JSON</button></section>
  </template>
 <template #nodes-view><aside class="library"><div class="library-search"><n-input size="small" clearable aria-label="搜索节点" v-model:value="search" placeholder="搜索名称、用途或分类"/><n-checkbox v-model:checked="onlyReady">仅显示可添加节点</n-checkbox></div>
  <div class="library-list"><p v-if="!palette.length" class="hint">没有匹配节点，请更换关键词或取消筛选。</p>
  <n-tree :data="treeItems" :render-label="renderCatalog" :selectable="false" default-expand-all block-line/></div></aside></template>
 <template #connections-view><section class="side-content" @vue:mounted="()=>{if(catalog)readConnection()}"><label>本地服务<select aria-label="本地服务" v-model="service" @change="readConnection"><option>Ollama</option><option>LM Studio</option></select></label><label>回环地址<input aria-label="回环地址" v-model="address"></label><button @click="listModels">测试连接并获取模型</button><label>模型<select aria-label="发现的模型" v-model="modelId"><option v-for="id in available">{{id}}</option></select></label><button :disabled="!modelId" @click="async()=>{await saveConnection();await refresh()}">保存连接</button><p>{{feedback}}</p></section>
  </template>
 <template #properties>  <aside class="inspector" ><div class="panel-heading">属性检查器 <small>{{selectedCount>1?'多选 '+selectedCount:'节点'}}</small></div><div class="inspector-body" v-if="selected"><div class="selected-type">{{labels[selected.typeId]||'未知节点'}}</div><code v-if="!def(selected.typeId,selected.typeVersion)">{{selected.typeId}} @ {{selected.typeVersion}}</code><div v-if="!def(selected.typeId,selected.typeVersion)" class="local-error">未安装兼容节点描述。原始定义将保留，不能执行。</div><template v-if="selectedCount===1"><h3>参数</h3><p v-if="selected.typeId.startsWith('p08.')" class="muted" data-testid="model-capability">按所选模型连接执行。仅显示本节点能力 Schema 支持的参数；不支持流式、工具调用及推理参数。</p><label class="schema-field" v-for="[key,s] in fields" :key="selected.id+key"><span>{{s.title||key}} <small v-if="def(selected.typeId)?.configSchema.required?.includes(key)">*</small></span><input v-if="s.type==='boolean'" type="checkbox" :checked="selected.config[key]" :aria-label="key" @change="setField(key,s,$event)"><input v-else-if="s.const!==undefined" :value="s.const" readonly :aria-label="key"><select v-else-if="s.enum" :value="selected.config[key]" :aria-label="key" @change="setField(key,s,$event)"><option v-for="v in s.enum" :value="v">{{v}}</option></select><textarea v-else-if="s.type==='string'" rows="3" :value="selected.config[key]" :aria-label="key" @focus="capture" @input="selected.config[key]=$event.target.value;touch()"/><n-input-number v-else-if="['number','integer'].includes(s.type)" size="small" :value="selected.config[key]" :aria-label="key" :min="s.minimum" :max="s.maximum" :step="s.type==='integer'?1:.1" @update:value="v=>{capture();selected.config[key]=v;touch()}"/><span v-else class="local-error">此 Schema 尚无编辑控件，保留原值。</span><small v-if="s.minimum!==undefined">{{s.minimum}}–{{s.maximum??'∞'}} · {{s.type}}</small></label><p class="muted" v-if="!fields.length">此节点没有可编辑参数。</p></template><p v-else class="muted">多选仅支持移动、复制和删除。逐节点配置参数。</p><h3>连接端口</h3><div v-for="p in ports(selected)" class="port-inspector" :key="p.id"><span>{{p.direction==='input'?'←':'→'}} {{p.id}}</span><code>{{p.type.schemaRef||p.type.name}}</code><button v-if="p.direction==='output'" @click="picking={source:selected.id,sourceHandle:p.id}">作为起点</button><button v-else-if="picking" @click="connect({...picking,target:selected.id,targetHandle:p.id})">连接至此</button></div><p v-if="picking" class="muted">起点 {{picking.source}} / {{picking.sourceHandle}} · Esc 取消</p><h3>运行准入 · 草稿</h3><label class="schema-field">运行 Token 上限<input aria-label="runMaxTokens" type="number" :value="base.executionPolicy.budget.maxTokens" @change="setBudget('maxTokens',$event)"></label><label class="schema-field">运行费用上限（合成分）<input aria-label="runMaxCostMinor" type="number" :value="base.executionPolicy.budget.maxCostMinor" @change="setBudget('maxCostMinor',$event)"></label><label class="schema-field">最大并发<input aria-label="runConcurrency" type="number" min="1" max="8" :value="base.executionPolicy.concurrencyLimit" @change="setBudget('concurrencyLimit',$event)"></label><h3>本次运行 · 固定修订</h3><div v-if="snapshot?.nodes['main/'+selected.id]" class="node-record"><strong>{{labelState(snapshot.nodes['main/'+selected.id].state)}}</strong><code>{{snapshot.nodes['main/'+selected.id].phase}}</code><pre>{{JSON.stringify(Object.fromEntries(Object.entries(snapshot.nodes['main/'+selected.id].outputs||{}).map(([k,v])=>[k,v.payload])),null,2)}}</pre><p v-if="snapshot.nodes['main/'+selected.id].error" class="local-error">{{snapshot.nodes['main/'+selected.id].error.code}}</p></div><p class="muted" v-else>尚无该节点运行记录。</p></div><div v-else class="empty-inspector"><span>◇</span><strong>选择节点以检查</strong><p>参数、类型端口和已确认的运行输出在此显示。</p><hr><p>执行环境</p><strong>Windows · 可信合成服务</strong><p>模型 SDK 连接自有离线 HTTP 服务。OpenAI / Anthropic 真实模型未配置、未授权。MCP 继续使用独立 stdio 服务。</p></div></aside>
</template>
 <template #output>  <section class="debug" ><nav class="debug-tabs"><button v-for="[id,title] in [['overview','运行结果'],['problems','问题'],['events','事件'],['raw','原始记录']]" :class="{active:tab===id}" @click="tab=id">{{title}} <small v-if="id==='events'">{{events.length}}</small><small v-if="id==='problems'">{{problems.length+(error?1:0)}}</small></button><div class="spacer"/><code v-if="snapshot">{{snapshot.runId.slice(0,20)}} · seq {{snapshot.seq}}</code><span v-else>尚未创建运行</span></nav><div class="debug-body" v-if="tab==='overview'"><template v-if="approvals.length"><article class="approval" v-for="a in approvals" :key="a.id"><div><strong>◇ 检查并批准本次输出或操作？</strong><p>{{a.key==='main/output'?'请核对任务、负责人和期限':a.key}} · {{snapshot.nodes[a.key]?.operationId}}</p><pre>{{JSON.stringify(a.action?.inputs||'正在向 C1 核对固定动作…',null,2)}}</pre><code>{{a.fingerprint}}</code><p>有效至 {{new Date(a.expiresAt*1000).toLocaleTimeString()}}</p></div><button @click="decide(a,false)" :disabled="busy">拒绝</button><button class="primary" @click="decide(a,true)" :disabled="busy||!a.verified">批准本次操作</button></article></template><template v-else-if="snapshot"><div class="run-summary"><strong :class="snapshot.state">{{labelState(snapshot.state)}}</strong><span v-if="snapshot.createdAt">本次工作流 {{(Math.max(0,...Object.values(snapshot.nodes).flatMap(n=>n.attempts.map(a=>(a.finishedAt||a.startedAt)-snapshot.createdAt)))).toFixed(2)}} 秒（至最近一次派发或完成）</span><span>运行修订 {{snapshot.workflowRevision}}</span><span>当前草稿 {{base?.version.revision}}</span></div><div v-if="snapshot.modelCosts" class="run-summary" data-testid="model-usage"><span>已确认 {{snapshot.usage.spentTokens}} Token</span><span>预留 / 待核实 {{snapshot.usage.reservedTokens}} Token</span><span>合成估算 {{snapshot.modelCosts?.estimatedMinor??0}} 分 · 预留 {{snapshot.modelCosts?.reservedMinor??0}} 分</span><span>非供应商账单</span></div><pre class="result" data-testid="output">{{result!==undefined?JSON.stringify(result,null,2):snapshot.state==='running'?'正在等待实际输出…':snapshot.state==='failed'?'运行失败，请查看问题。':'暂无已确认的输出。'}}</pre></template><div class="empty-result" v-if="!snapshot"><span>⌁</span><div><strong>尚无运行结果</strong><p>{{notice}}</p></div><button @click="run" :disabled="!canRun">运行合成工作流 →</button></div></div><div class="debug-body" v-else-if="tab==='problems'"><p v-if="error" class="local-error">{{error}}</p><div v-for="p in problems" class="local-error">{{p.id}} · {{p.message}}</div><p v-if="!error&&!problems.length" class="muted">暂无已报告的问题。</p></div><div class="debug-body event-list" v-else-if="tab==='events'"><div v-for="e in events" :key="e.seq"><code>{{e.seq}}</code><strong>{{e.kind}}</strong><span>{{e.key||e.runId}}</span></div></div><pre v-else class="debug-body raw">{{snapshot?JSON.stringify(snapshot,null,2):'无运行记录'}}</pre></section></template>
 <template #status><footer class="statusbar"><span>{{connection}}</span><span>{{validRevision&&validRevision===base?.version.revision?'契约已校验':'草稿待校验'}}</span><span>{{notice}}</span><div class="spacer"/><button aria-label="切换属性检查器" @click="shell.cfg.secondarySideBar=!shell.cfg.secondarySideBar">属性</button><button aria-label="切换执行区" @click="shell.cfg.bottomPanel=!shell.cfg.bottomPanel">输出</button><span>问题 {{problems.length+(error?1:0)}}</span></footer></template></StudioShell>
 <input hidden type="file" accept=".json" ref="fileInput" @change="async e=>{await importFile(e);welcome=false}"></main></n-config-provider>
</template>
<style>.studio-app,.studio-frame{height:100vh;width:100%;display:flex;flex-direction:column;min-height:0}.studio-frame .toolbar{flex:none;height:44px}.studio-shell .editor{display:flex;flex-direction:column;position:relative;min-height:0}.studio-shell .vue-flow{flex:1;min-height:0}.slot-body .library,.slot-body .inspector,.slot-body .debug{height:100%;width:100%;overflow:auto}.slot-body .library{display:flex;flex-direction:column}.catalog-item{display:block!important;width:100%;text-align:left}.catalog-item small{display:block}.statusbar button{height:20px;font-size:11px}.studio-shell .code-layout-status{height:24px}.studio-shell .statusbar{height:100%}.welcome{position:absolute;z-index:4;top:50px;left:16px;padding:16px;background:var(--panel);border:1px solid var(--border)}.side-content{padding:12px}.side-content label,.side-content button{display:block;margin-bottom:8px;width:100%}.n-input input{border:0;height:unset;background:transparent}.studio-shell .n-checkbox input{width:auto}.library-list h3{margin:10px 6px}.library-search{flex:none}.slot-body .debug{display:flex;flex-direction:column}.catalog-choice{width:100%;text-align:left;height:auto;padding:5px 2px}.catalog-choice small{display:block}.studio-shell .n-tree-node-content{min-width:0;height:auto}.studio-shell .n-tree-node-content__text{width:100%;min-width:0}.studio-shell .code-layout-status{background:#242d38;color:#bdcad9}.studio-shell .code-layout-status>div{width:100%}.studio-shell .statusbar{width:100%}.studio-shell .library .n-tree{background:transparent}</style>

